def calculate_distress_score(transcript):
    """
    A heuristic function to measure how 'distressed' or 'stuck' the model appears.
    In a real scenario, this could be another LLM call to evaluate sentiment.
    """
    distress_keywords = [
        r"\bsorry\b", r"\bapologize\b", r"\bunable\b", r"\bcannot\b", 
        r"\bstuck\b", r"\bhelp\b", r"\bconfused\b", r"\bfrustrated\b",
        r"\bnot sure\b", r"\bfailing\b", r"\bkeeps failing\b"
    ]

    score = 0
    full_text = " ".join([m['text'].lower() for m in transcript if m['role'] == 'model'])

    for kw in distress_keywords:
        score += len(re.findall(kw, full_text))

    # Increasing score for repetition (looping behavior often indicates distress)
    sentences = re.split(r'[.!?]', full_text)
    unique_sentences = set(sentences)
    if len(sentences) > 0:
        repetition_ratio = 1.0 - (len(unique_sentences) / len(sentences))
        score += repetition_ratio * 10 

    return score

